import React, { useEffect, useState } from 'react';

export default function Events() {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [editingEvent, setEditingEvent] = useState(null);
  const [showEditForm, setShowEditForm] = useState(false);


  const updateCount = async (id, action) => {
    try {
      const res = await fetch(`http://localhost:5000/api/events/${id}/${action}`, {
        method: 'POST'
      });
      if (!res.ok) throw new Error('Failed to update');
      const updated = await res.json();
      // Ensure events is an array before mapping
      setEvents(prevEvents => {
        const eventsArray = Array.isArray(prevEvents) ? prevEvents : [];
        return eventsArray.map(e => (e._id === id ? updated : e));
      });
    } catch (err) {
      setError(err.message);
    }
  };

  useEffect(() => {
    fetch('http://localhost:5000/api/events')
      .then(res => {
        if (!res.ok) {
          throw new Error('Failed to fetch events');
        }
        return res.json();
      })
      .then(data => {
        // Extract events array from API response
        const eventsData = data && data.data ? data.data : [];
        setEvents(eventsData);
        setLoading(false);
      })
      .catch(err => {
        console.error('Error fetching events:', err);
        setError(err.message);
        setEvents([]); // Set to empty array on error
        setLoading(false);
      });
  }, []);

  if (loading) return <p>Loading events...</p>;
  if (error) return <p style={{ color: 'red' }}>{error}</p>;

  // Additional safety check
  if (!Array.isArray(events)) {
    console.error('Events is not an array:', events);
    return <p style={{ color: 'red' }}>Error: Events data is not properly formatted</p>;
  }

  return (
    <div className="container" style={{ padding: '40px 0' }}>
      <h2>Events</h2>
      <ul className="list-group">
        {events.map(evt => (
          <li key={evt._id} className="list-group-item">
            <strong>{evt.title}</strong> ({new Date(evt.date).toLocaleString()})<br />
            Category: {evt.category} | Faculty: {evt.faculty} | Capacity: {evt.capacity}<br />
            Registrations: {evt.registrationCount} | Attendance: {evt.attendanceCount}<br />
            Status: {evt.status}
            <div style={{ marginTop: 6 }}>
              <button
                className="btn btn-sm btn-primary"
                onClick={() => updateCount(evt._id, 'register')}
              >
                +Register
              </button>{' '}
              <button
                className="btn btn-sm btn-success"
                onClick={() => updateCount(evt._id, 'checkin')}
              >
                +Check‑In
              </button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
